'use strict';
const E=QuestEngine,Q=QUESTIONS,$=s=>document.querySelector(s), byId=id=>Q.find(q=>q.id===id);
const chapters=[['JS','语言基石','作用域、闭包、this 与原型链'],['↻','异步秘境','事件循环、Promise 与防抖'],['{ }','数据工坊','类型、拷贝、数组与事件'],['⚛','React 之森','状态、Hooks 与组件身份'],['⌁','进阶高地','性能、状态管理与架构'],['⚑','实战城堡','手写代码与真实项目表达']];
let storageError=false,state=E.fresh(),page='home',filter='all',search='',tab='all',result=null,toastTimer;
try{const raw=localStorage.getItem(E.KEY);if(raw){const parsed=JSON.parse(raw);state=E.validate(parsed,Q.map(q=>q.id));if(parsed.active&&Array.isArray(parsed.active.ids)&&parsed.active.ids.every(id=>byId(id))&&Number.isInteger(parsed.active.index)&&parsed.active.index>=0&&parsed.active.index<parsed.active.ids.length&&Array.isArray(parsed.active.results)&&parsed.active.results.every(r=>byId(r.id)&&[0,1,2].includes(r.grade)))state.active=parsed.active;}}catch{storageError=true;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rec=id=>E.record(state,id), today=()=>state.days[E.dayKey()]||{ids:[],xp:0,attempts:0}, due=()=>Q.filter(q=>rec(q.id).seen&&rec(q.id).due<=Date.now()), wrong=()=>Q.filter(q=>rec(q.id).wrong), learned=()=>Q.filter(q=>rec(q.id).level>=3), seen=()=>Q.filter(q=>rec(q.id).seen), level=()=>Math.floor(state.xp/200)+1;
function save(){try{localStorage.setItem(E.KEY,JSON.stringify(state));storageError=false;}catch{storageError=true;toast('浏览器无法保存进度，请在成长记录中导出存档。');}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3600);}
function source(q){return `<div class="source">来源：${q.source==='top'?'高频面试题':'中文复习清单'} · 第 ${q.page} 页 · ${q.id}${q.source==='guide'?' · 练习改编':''}${q.url?` · <a href="${esc(q.url)}" target="_blank" rel="noopener">官方说明 ↗</a>`:''}</div>`;}
function nav(p){if($('#detail').open)$('#detail').close();page=p;search='';filter='all';tab='all';render();window.scrollTo({top:0});}
function iconScene(){return `<svg class="hero-art" viewBox="0 0 300 250" aria-hidden="true"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#afc199" opacity=".3"/></pattern></defs><rect width="300" height="250" fill="url(#dots)"/><circle cx="225" cy="50" r="22" fill="#f8e6a5"/><path d="M0 213 80 160 140 185 220 128 300 170V250H0Z" fill="#ceddbc"/><path d="m0 244 86-56 79 29 72-37 63 25v45H0" fill="#b5cca1"/><path d="m28 250 82-32 33 8 90-24" fill="none" stroke="#e9edcd" stroke-width="17"/><g fill="#8ca67b"><rect x="244" y="143" width="8" height="48"/><path d="m248 92-29 60h58Zm0 22-35 58h70Z"/><rect x="40" y="175" width="6" height="35"/><path d="m43 132-23 51h46Zm0 18-29 48h58Z"/></g><g transform="translate(83 78)"><path d="m0 23 65-30 71 34-65 32Z" fill="#eff4df"/><path d="m0 23 71 36v76L0 97Z" fill="#749873"/><path d="m71 59 65-32v73l-65 35Z" fill="#4e7a5a"/><path d="m12 37 50 25v51L12 87Z" fill="#345f4a"/><path d="m22 56 12-1-8 12 10 19m14-20-7 19" fill="none" stroke="#dbe8ac" stroke-width="4"/><path d="m85 62 37-18v37l-37 18Z" fill="#9bbc84"/><path d="m93 65 20-10v19l-20 10Z" fill="#315c47"/><path d="m31 8 34-15 37 18-34 16Z" fill="#d0dfb8"/><rect x="61" y="-35" width="5" height="33" fill="#436c4e"/><path d="m66-35 33 8-33 10" fill="#dba65b"/></g><g fill="#f7e4a3"><path d="m70 60 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/><path d="m244 207 2 5 5 2-5 2-2 5-2-5-5-2 5-2Z"/></g><g transform="translate(162 198)"><rect x="3" y="0" width="18" height="16" fill="#f4cd88"/><rect x="0" y="-4" width="24" height="8" fill="#4b6e45"/><rect x="5" y="15" width="15" height="18" fill="#d5a257"/><rect x="6" y="33" width="5" height="7" fill="#355941"/><rect x="16" y="33" width="5" height="7" fill="#355941"/><rect x="16" y="6" width="3" height="3" fill="#355941"/><rect x="-1" y="16" width="6" height="15" fill="#5e8153"/></g></svg>`;}
function shell(inner){const navigation=[['home','▦','冒险营地'],['chapters','◇','闯关地图'],['review','↻','记忆补给站'],['library','▤','知识图鉴'],['progress','◴','成长记录']];return `<aside class="sidebar"><button class="brand" data-nav="home"><img src="icon.svg" alt=""><span><strong>前端冒险</strong><small>FRONTEND QUEST</small></span></button><div class="nav-label">你的冒险</div><nav>${navigation.map(([p,i,t])=>`<button class="navitem ${page===p?'active':''}" data-nav="${p}"><span class="navicon">${i}</span>${t}${p==='review'&&due().length?`<span class="navbadge">${due().length}</span>`:''}</button>`).join('')}</nav><div class="nav-label desktoponly">特别挑战</div><button class="navitem desktoponly ${page==='boss'?'active':''}" data-nav="boss"><span class="navicon">⚑</span>面试 Boss 战</button><div class="sidebar-bottom"><div class="save-note"><b>● 进度自动保存在此浏览器</b>每天一点，把「看过」变成「会了」。<br>换设备前记得导出存档。</div><div class="profile"><div class="avatar">🌱</div><div><strong>${level()<4?'前端探索者':level()<8?'知识游侠':'面试冒险家'}</strong><small>LEVEL ${level()} · 继续生长</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">我的学习空间 <span style="padding:0 13px">/</span> <b>${({home:'冒险营地',chapters:'闯关地图',review:'记忆补给站',library:'知识图鉴',progress:'成长记录',boss:'面试 Boss 战',practice:'训练进行中',results:'冒险结算'})[page]}</b></div><button class="mobilebrand" data-nav="home">⌘ 前端冒险</button><div class="headerstats"><span><strong class="orange">♨ ${E.streak(state)}</strong> 天连续</span><span><strong>✦ ${state.xp}</strong> XP</span><span class="levelpill">Lv. ${level()}</span></div></header><div class="content">${storageError?'<div class="error-banner">浏览器存档不可用或原存档无法读取。请使用「成长记录 → 导出存档」备份本次进度。</div>':''}${inner}<footer class="footer">一步一个知识点，让记忆长出根。 <span class="en"> · BUILT FOR YOUR NEXT INTERVIEW</span></footer></div></main>`;}
function home(){const ids=E.daily(state,Q),d=today(),done=ids.filter(id=>d.ids.includes(id)).length,master=learned().length,first=chapters.findIndex((_,i)=>Q.filter(q=>q.chapter===i).some(q=>!rec(q.id).seen));save();return `<div class="intro"><div><div class="eyebrow">A LITTLE PROGRESS, EVERY DAY</div><h1>今天，也向前一步 <span style="font-size:24px">🌿</span></h1><p>不只是记住答案，更要把知识变成你的直觉。</p></div><span class="datepill">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span></div>${state.active?'<div class="info-banner sessions-banner"><span>上次的冒险还在等你，已完成的题目已保存。</span><button class="secondary" data-action="resume">继续训练 →</button></div>':''}<div class="grid-home"><div><section class="hero"><div class="hero-copy"><span class="tag">✦ 每日任务 · 约 10 分钟</span><h2>${done===6?'今日任务，已完成！':'今天的经验值，'}${done===6?'':'<br>从 6 道题开始。'}</h2><p>3 道 JavaScript + 3 道 React<br>先回忆，再理解，让知识真正留下来。</p><button class="primary" data-action="daily">${done===6?'再来一轮练习':'开始今日冒险'} <span>→</span></button></div>${iconScene()}</section><div class="stats-row"><div class="stat"><div class="stat-icon">▤</div><div><strong>${seen().length}<span style="font-size:12px;font-weight:400;color:#a0ab96"> / ${Q.length}</span></strong><small>已探索知识点</small></div></div><div class="stat"><div class="stat-icon">↻</div><div><strong>${due().length}</strong><small>到期需复习</small></div></div><div class="stat"><div class="stat-icon">♧</div><div><strong>${master}</strong><small>逐渐扎根</small></div></div></div><div class="section-head"><h2>你的冒险地图</h2><button class="text-button" data-nav="chapters">探索全部章节 ↗</button></div><section class="map"><div class="map-header"><span class="dot"></span> 从基础到实战，一路点亮知识版图</div><div class="map-stage"><svg class="map-path" viewBox="0 0 560 240" preserveAspectRatio="none" aria-hidden="true"><path d="M18 55H490Q548 55 548 125Q548 195 490 195H18" fill="none" stroke="#e6ebdc" stroke-width="11" stroke-linecap="round"/><path d="M18 55H490Q548 55 548 125Q548 195 490 195H18" fill="none" stroke="#cddbbd" stroke-width="2" stroke-dasharray="4 9"/></svg>${chapters.map(([ic,title],i)=>{const group=Q.filter(q=>q.chapter===i),n=group.filter(q=>rec(q.id).seen).length;return `<button class="map-node ${i===Math.max(0,first)?'current':''} ${n===group.length?'complete':''}" data-chapter="${i}" aria-label="进入第 ${i+1} 章 ${title}"><span class="node-icon">${ic}</span><strong>${String(i+1).padStart(2,'0')} · ${title}</strong><small>${n} / ${group.length} 已探索</small></button>`;}).join('')}</div><div class="map-legend"><span>● 当前推荐 &nbsp; ◌ 可自由探索</span><span>不设门槛，按你的节奏前进</span></div></section><div class="modes"><button class="mode" data-action="flash"><span class="symbol">▱</span><div><strong>记忆闪卡</strong><small>合上答案，试着讲给自己听</small></div><span class="arrow">↗</span></button><button class="mode" data-nav="boss"><span class="symbol">⚑</span><div><strong>面试 Boss 战</strong><small>6 轮追问，把理解说清楚</small></div><span class="arrow">↗</span></button></div></div><aside class="rail"><section class="panel"><div class="panel-head"><h3>今日小目标</h3><span>每日刷新</span></div><div class="goal-circle" style="--progress:${done/6*100}%"><div><strong>${done}<span style="font-size:17px;color:#a1ad94;letter-spacing:0"> / 6</span></strong><small>道题已探索</small></div></div><p class="daily-caption">${done===6?'今日已完成，明天继续生长。':'保持节奏，比一口气刷完更重要。'}</p>${[['JavaScript 练习',ids.filter(id=>id.startsWith('J'))],['React 练习',ids.filter(id=>!id.startsWith('J'))]].map(([label,a])=>`<div class="goal-task ${a.every(id=>d.ids.includes(id))?'done':''}"><i class="tinycheck">${a.every(id=>d.ids.includes(id))?'✓':''}</i>${label}<span>${a.filter(id=>d.ids.includes(id)).length} / 3</span></div>`).join('')}<div class="divider"></div><div class="row"><small class="muted" style="font-size:10px">今天收获</small><span class="en" style="font-size:12px;color:#bd9950">✦ ${d.xp} XP</span></div></section><section class="panel"><div class="panel-head"><h3>冒险徽章</h3><button class="text-button" data-nav="progress">全部 ↗</button></div><div class="badge-grid">${badges().slice(0,3).map(b=>`<div class="badge ${b.ok?'earned':''}" title="${b.desc}"><div class="medal">${b.icon}</div>${b.name}</div>`).join('')}</div><small class="muted" style="font-size:10px">每一次认真练习，都值得被看见。</small></section><section class="panel tip"><h3>✧ 记忆小锦囊</h3><p>先别急着翻答案。<br>用一句话解释原理，再举一个例子。<br>「想起来」的过程，就是记住的开始。</p><div class="en">RECALL → UNDERSTAND → REMEMBER</div></section></aside></div>`;}
function badges(){return [{name:'初次启程',icon:'⚑',ok:seen().length>=1,desc:'完成第一张练习卡'},{name:'坚持萌芽',icon:'♧',ok:E.streak(state)>=3,desc:'连续练习 3 天'},{name:'记忆生根',icon:'✦',ok:learned().length>=1,desc:'至少 1 题完成 3 次到期且跨天的熟练复习'},{name:'双栖探索',icon:'⌘',ok:Q.some(q=>q.id[0]==='J'&&rec(q.id).seen)&&Q.some(q=>q.id[0]==='R'&&rec(q.id).seen),desc:'分别练习 JS 和 React'},{name:'实战勇者',icon:'⚒',ok:Q.filter(q=>q.kind==='code').every(q=>rec(q.id).seen),desc:'完成 5 道手写自查练习'},{name:'表达之星',icon:'♜',ok:state.bossWins>0,desc:'Boss 战自评至少 4 题达到熟练'}];}
function chaptersPage(){return `<div class="pageheader"><div><div class="eyebrow">THE LEARNING PATH</div><h1>每一章，都是新的领地</h1><p>6 个主题 · ${Q.length} 张练习卡 · 章节自由进入</p></div></div><div class="cards">${chapters.map(([ic,title,desc],i)=>{const group=Q.filter(q=>q.chapter===i),n=group.filter(q=>rec(q.id).seen).length;return `<button class="chapter-card" data-chapter="${i}"><div class="row"><span class="chapter-icon">${ic}</span><span class="pill">CHAPTER 0${i+1}</span></div><h3>${title}</h3><p>${desc}</p><div class="bar"><span style="width:${n/group.length*100}%"></span></div><div class="row"><small class="muted">${n} / ${group.length} 已探索</small><span>进入 →</span></div></button>`;}).join('')}</div><div class="info-banner" style="margin-top:24px">每轮最多 6 题，优先安排到期内容与新题。正确选择只是起点，读完解析后请用自己的话再讲一次。</div>`;}
function statusLabel(q){const r=rec(q.id);return !r.seen?'未探索':r.wrong?'待巩固':r.due<=Date.now()?'到期复习':r.level>=3?'已扎根':`生长中 ${r.level}/3`;}
function qRow(q){return `<button class="question-row" data-detail="${q.id}"><span class="question-id">${q.id}</span><span><strong>${esc(q.title)}</strong><small>${chapters[q.chapter][1]} · ${q.kind==='quiz'?'概念 / 代码判断':q.kind==='code'?'手写自查':'项目表达'}</small></span><span class="right">${state.bookmarks.includes(q.id)?'<span style="color:#bf9953">★</span>':''}<span class="pill ${rec(q.id).wrong?'orange':''}">${statusLabel(q)}</span><span class="muted">›</span></span></button>`;}
function library(){return `<div class="pageheader"><div><div class="eyebrow">KNOWLEDGE FIELD GUIDE</div><h1>知识图鉴</h1><p>两份 PDF，重新整理成 ${Q.length} 个可练习的知识点。</p></div><button class="secondary" data-action="sources">资料与勘误 ↗</button></div><div class="toolbar"><input class="search" id="search" type="search" aria-label="搜索知识点" placeholder="搜索闭包、useEffect、Promise…" value="${esc(search)}"><select class="select" id="filter" aria-label="按章节筛选"><option value="all">全部章节</option>${chapters.map((c,i)=>`<option value="${i}" ${filter===String(i)?'selected':''}>${c[1]}</option>`).join('')}</select><button class="secondary ${tab==='bookmarks'?'active':''}" data-action="bookmarks">★ 我的收藏</button></div><div id="libraryRows">${libraryRows()}</div>`;}
function libraryRows(){const list=Q.filter(q=>(filter==='all'||String(q.chapter)===filter)&&(tab!=='bookmarks'||state.bookmarks.includes(q.id))&&`${q.title} ${q.id} ${q.prompt} ${q.answer}`.toLowerCase().includes(search.toLowerCase()));return `<p class="muted" style="font-size:11px;margin:0 0 13px">找到 ${list.length} 个知识点</p><div class="question-list">${list.length?list.map(qRow).join(''):'<div class="empty"><h2>这里还没有知识点</h2><p>换一个关键词，或在题目中点击星星添加收藏。</p></div>'}</div>`;}
function review(){const list=tab==='wrong'?wrong():due();return `<div class="pageheader"><div><div class="eyebrow">GROW YOUR MEMORY</div><h1>记忆补给站</h1><p>把快忘记的捡回来，把还不熟的再练一次。</p></div>${list.length?`<button class="primary" data-action="reviewStart">开始复习 ${Math.min(6,list.length)} 题 →</button>`:''}</div><div class="toolbar"><button class="secondary ${tab!=='wrong'?'active':''}" data-reviewtab="due">到期复习 · ${due().length}</button><button class="secondary ${tab==='wrong'?'active':''}" data-reviewtab="wrong">错题与薄弱点 · ${wrong().length}</button></div><div class="info-banner">忘了：10 分钟后再见 · 模糊：1 天后再见 · 会讲：按 1 / 3 / 7 / 14 / 30 天延长间隔。当天重复刷题不增加掌握等级。</div>${list.length?`<div class="question-list">${list.map(qRow).join('')}</div>`:`<div class="empty"><div style="font-size:40px;margin-bottom:14px">🌱</div><h2>${tab==='wrong'?'暂时没有待巩固的题':'现在没有到期的复习'}</h2><p>${seen().length?'已经练过的知识正在生长。你可以先探索新章节。':'先完成一轮练习，这里会自动安排你的复习内容。'}</p><button class="primary" data-action="daily">去做今日任务 →</button></div>`}`;}
function progress(){const bs=badges(),cells=[];for(let i=27;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=E.dayKey(d),n=state.days[key]?.ids.length||0;cells.push(`<div class="heatcell ${n>=6?'hot':n?'warm':''}" title="${key}：${n} 个知识点" aria-label="${key}：${n} 个知识点"></div>`);}return `<div class="pageheader"><div><div class="eyebrow">SMALL STEPS. REAL GROWTH.</div><h1>看见你的成长</h1><p>知识的熟悉感，会慢慢长成说得清楚的底气。</p></div></div><div class="metrics">${[[state.xp,'累计经验 XP'],[E.streak(state),'连续练习天数'],[seen().length,'已探索 / 61'],[learned().length,'已扎根知识点']].map(([n,t])=>`<div class="metric"><strong>${n}</strong><small>${t}</small></div>`).join('')}</div><div class="two-col"><section class="panel"><div class="panel-head"><h3>最近 28 天</h3><span>浅：1–5 题 · 深：6 题以上</span></div><div class="heatmap">${cells.join('')}</div><div class="row"><small class="muted">28 天前</small><small class="muted">今天</small></div><div class="divider"></div><p class="guide-text">「已扎根」需要 3 次跨天、到期的熟练复习。选择题与自评反映的是练习表现，不代表真实面试评分。</p></section><section class="panel"><h3>徽章收藏 · ${bs.filter(b=>b.ok).length} / ${bs.length}</h3><div class="badge-grid">${bs.map(b=>`<div class="badge ${b.ok?'earned':''}" title="${b.desc}"><div class="medal">${b.icon}</div>${b.name}</div>`).join('')}</div><div class="guide-text">${bs.filter(b=>!b.ok).slice(0,2).map(b=>`<p>下一步：${b.desc}</p>`).join('')||'所有徽章都已点亮，继续保持复习节奏。'}</div></section></div><section class="panel"><h3>你的学习档案</h3><p class="guide-text" style="margin-top:12px">进度、错题、收藏和笔记仅保存在当前浏览器，不会自动跨设备同步。清理浏览器数据前请导出存档；换设备后可导入继续。每题每天首次完成获得 XP，反复刷同一题不会重复加分。</p><div class="settings-buttons"><button class="secondary" data-action="export">↓ 导出存档</button><button class="secondary" data-action="import">↑ 导入存档</button><button class="secondary" data-action="sources">查看资料与学习规则</button></div></section>`;}
function boss(){return `<div class="bossintro"><div class="quiz-card"><span class="pill">EXPRESSION CHALLENGE</span><div style="font-size:58px;margin-top:18px">⚑</div><h1>准备好，迎接面试官了吗？</h1><p>从 JS 到 React，再到你的项目经历。<br>不看选项，试着先把答案说完整，再对照要点自评。</p><div class="boss-rules"><div><strong>6 轮问题</strong><small>2 JS + 2 React + 2 实战</small></div><div><strong>原理 → 例子</strong><small>每题建议表达 60–90 秒</small></div><div><strong>追问一层</strong><small>边界与取舍，说清为什么</small></div></div><p style="font-size:11px">这是自我表达训练，采用要点自查，不是 AI 评分。<br>无需麦克风权限，可开口练习，也可写下答案。</p><button class="primary" data-action="bossStart">进入 Boss 战 →</button></div></div>`;}
function start(ids,mode,title){if(state.active&&!confirm('将结束尚未完成的那一轮，已完成题目的进度会保留。开始新的训练吗？'))return;const list=ids.slice(0,6);if(!list.length){toast('目前没有可复习的题目');return;}state.active={ids:list,index:0,mode,title,results:[],start:Date.now(),selected:null,revealed:false,order:null,retries:[],xp:0};prepare();page='practice';save();render();scrollTo(0,0);}
function prepare(){const a=state.active;a.selected=null;a.revealed=false;a.order=E.shuffle(byId(a.ids[a.index]).choices.map((_,i)=>i));}
function isRecall(a,q){return ['flash','boss','recall'].includes(a.mode)||q.kind!=='quiz';}
function feedback(q,a){const recall=isRecall(a,q),ok=a.selected===0;return `<section class="feedback"><h3 class="result ${!recall&&!ok?'bad':''}">${recall?'对照要点，检查自己的解释':ok?'✓ 判断正确，再把原理讲一遍':'↻ 找到一个值得记住的盲点'}</h3><p>${esc(q.answer)}</p><ul class="checklist">${q.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><div class="memory">✧ 记忆锚点：${esc(q.memory)}</div>${recall&&q.code?`<details><summary>查看参考代码（先完成自己的草稿）</summary><pre class="code">${esc(q.code)}</pre></details>`:''}<details><summary>English · 面试回答骨架</summary><p class="english">${esc(q.english)}</p></details><div class="followup"><b>面试官可能继续问</b>${esc(q.follow)}</div>${q.note?`<div class="correction">${esc(q.note)}</div>`:''}${recall?`<div style="margin-top:18px"><small class="muted">自查：这些要点你刚才讲到了吗？</small>${q.points.map((p,i)=>`<label class="self-check"><input type="checkbox" data-check="${i}"><span>${esc(p)}</span></label>`).join('')}</div>`:''}${source(q)}<div class="divider"></div><small class="muted">${!recall&&!ok?'本题会在本轮末尾再出现一次，读懂后先继续。':'结合刚才的回忆，诚实选择熟悉程度：'}</small><div class="ratings"><button class="rating" data-grade="0">${!recall&&!ok?'记下盲点，继续':'还没想起来'}<small>10 分钟后复习</small></button><button class="rating" data-grade="1" ${!recall&&!ok?'disabled':''}>有点模糊<small>1 天后再巩固</small></button><button class="rating" data-grade="2" ${!recall&&!ok?'disabled':''}>${recall?'要点完整，能讲清':'能独立讲清楚'}<small>${recall?'请先勾选全部要点':'延长复习间隔'}</small></button></div></section>`;}
function practice(){const a=state.active;if(!a){page='home';return home();}const q=byId(a.ids[a.index]),recall=isRecall(a,q);return `<div class="practice-shell"><div class="session-top"><button class="secondary" data-nav="home">← 暂存离开</button><div class="bar"><span style="width:${a.index/a.ids.length*100}%"></span></div><small>${a.index+1} / ${a.ids.length}</small></div><div class="quiz-card"><div class="quiz-meta"><span class="pill">${esc(a.title)}</span><span class="pill ${q.chapter<3?'orange':'blue'}">${q.chapter<3?'JAVASCRIPT':q.chapter<5?'REACT':'PRACTICE'}</span><button class="bookmark" data-bookmark="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'取消收藏':'收藏本题'}">${state.bookmarks.includes(q.id)?'★':'☆'}</button></div><div class="eyebrow">${q.id} / ${esc(q.title)}</div><h2>${esc(recall&&q.kind==='quiz'?`请解释「${q.title}」，给一个例子，并说明一个容易出错的边界。`:q.prompt)}</h2><div class="prompt-note">${recall?'主动回忆 · 先用自己的话讲，卡住也没关系。':'先想再选 · 请先在心里说出理由，再选择答案。'}</div>${!recall&&q.code?`<pre class="code">${esc(q.code)}</pre>`:''}${recall?`<label class="notes-label" for="scratch">${q.kind==='code'?'你的代码草稿 · 手写与自查，不在浏览器执行':'你的回答草稿 · 自动保存，可直接开口练习'}</label><textarea id="scratch" class="answer-input ${q.kind==='code'?'coding':''}" data-note="${q.id}" placeholder="${q.kind==='code'?'// 先独立写出思路与实现，再对照参考答案':'原理是什么？\n举一个例子。\n项目里怎么用，有什么取舍？'}">${esc(state.notes[q.id]||'')}</textarea>`:`<div class="choices">${a.order.map((idx,i)=>`<button class="choice ${a.selected===idx?'selected':''} ${a.revealed?(idx===0?'correct':idx===a.selected?'wrong':''):''}" data-choice="${idx}" ${a.revealed?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(q.choices[idx])}</span></button>`).join('')}</div>`}${!a.revealed?`<div class="quiz-actions"><small>${recall?'写下或说完后，打开答案自查。':'答错不扣经验，发现盲点也是进步。'}</small><button class="primary" data-action="reveal" ${!recall&&a.selected===null?'disabled':''}>${recall?'查看答案，开始自查':'确认答案'} →</button></div>`:feedback(q,a)}</div><p class="recall-tip" style="margin:18px 0;text-align:center">${a.mode==='boss'?'Boss 战采用自评。请用真实经历作答，不需要编造项目结果。':'同一道题每天仅首次获得 XP；跨天且到期的复习才提升掌握等级。'}</p></div>`;}
function grade(n){const a=state.active,q=byId(a.ids[a.index]);if(!a.revealed)return;if(!isRecall(a,q)&&a.selected!==0)n=0;if(isRecall(a,q)&&n===2&&document.querySelectorAll('[data-check]:checked').length<q.points.length){toast('先逐项核对：全部讲到才算“能讲清”。');return;}const gain=E.rate(state,q.id,n);a.xp+=gain;a.results.push({id:q.id,grade:n});if(n===0&&!a.retries.includes(q.id)){a.ids.push(q.id);a.retries.push(q.id);}a.index++;if(a.index>=a.ids.length){const final={};for(const r of a.results)final[r.id]=r.grade;const good=Object.values(final).filter(v=>v===2).length;if(a.mode==='boss'&&good>=4)state.bossWins++;result={...a,good,count:Object.keys(final).length,final};state.active=null;page='results';}else prepare();save();render();scrollTo(0,0);if(gain)toast(`+${gain} XP · ${n===0?'盲点已记录，将在本轮重练':n===1?'明天再巩固一次':'记忆又生长了一点'}`);}
function results(){if(!result){page='home';return home();}const weak=Object.entries(result.final).filter(([,v])=>v<2).map(([id])=>byId(id));return `<div class="results"><div class="eyebrow">QUEST COMPLETE</div><div class="trophy">${weak.length?'🌱':'🏆'}</div><h1>${weak.length?'又向前走了一小步':'这一轮，收获满满！'}</h1><p>完成 ${result.count} 个知识点。比起全对，更重要的是知道下一步练什么。</p><div class="stats-row"><div class="stat"><strong>+${result.xp}</strong><small>本轮经验 XP</small></div><div class="stat"><strong>${result.good} / ${result.count}</strong><small>自评能讲清</small></div><div class="stat"><strong>${weak.length}</strong><small>继续巩固</small></div></div>${weak.length?`<div class="section-head"><h2>下次，重点照顾它们</h2></div><div class="question-list">${weak.map(qRow).join('')}</div>`:'<div class="info-banner">下一次复习会按到期时间安排。隔一段时间还能想起来，记忆才更牢固。</div>'}<div class="result-buttons"><button class="primary" data-nav="home">回到冒险营地 →</button><button class="secondary" data-nav="review">查看复习安排</button></div></div>`;}
function render(){const views={home,chapters:chaptersPage,review,library,progress,boss,practice,results};$('#app').innerHTML=shell((views[page]||home)());}
function toggleBookmark(id){state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(v=>v!==id):[...state.bookmarks,id];save();toast(state.bookmarks.includes(id)?'已加入收藏':'已取消收藏');if($('#detail').open)detail(id);else render();}
function detail(id){const q=byId(id),r=rec(id);$('#detail').innerHTML=`<button class="dialog-close" data-action="close" aria-label="关闭">×</button><span class="pill">${id} · ${chapters[q.chapter][1]}</span><h2 style="margin:17px 0 8px">${esc(q.title)}</h2><p class="muted" style="font-size:11px">${statusLabel(q)}${r.seen?` · 下次复习：${new Date(r.due).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}`:''}</p><div class="answer-body"><p>${esc(q.answer)}</p><ul class="checklist">${q.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><div class="memory">✧ ${esc(q.memory)}</div>${q.code?`<pre class="code">${esc(q.code)}</pre>`:''}<details><summary>English · 面试回答骨架</summary><p class="english">${esc(q.english)}</p></details><div class="followup"><b>继续追问</b>${esc(q.follow)}</div>${q.note?`<div class="correction">${esc(q.note)}</div>`:''}${source(q)}<label class="notes-label" for="detailNote">我的理解 / 项目例子</label><textarea id="detailNote" class="answer-input" data-note="${id}" placeholder="把自己的理解留在这里…">${esc(state.notes[id]||'')}</textarea><div class="dialog-actions"><button class="primary" data-single="${id}">合上答案，练一次 →</button><button class="secondary" data-bookmark="${id}">${state.bookmarks.includes(id)?'★ 已收藏':'☆ 收藏知识点'}</button></div></div>`;if(!$('#detail').open)$('#detail').showModal();}
function sources(){const fixed=Q.filter(q=>q.note);$('#detail').innerHTML=`<button class="dialog-close" data-action="close" aria-label="关闭">×</button><div class="eyebrow">ABOUT YOUR FIELD GUIDE</div><h2>资料来源与学习规则</h2><div class="answer-body"><p>内容根据你提供的两份 PDF 改编：React_JavaScript_Interview_Guide_CN.pdf（3 页）与 react-javascript-top-questions.pdf（14 页）。包含 46 个原高频主题、4 个清单补充概念、5 道手写题和 6 道项目追问。题目与参考解答经过重新编写，每题保留来源页码。</p><div class="memory">先回忆 → 做判断 / 手写 → 对照解析 → 用自己的话表达 → 间隔复习。</div><p>每日任务固定为 3 道 JS + 3 道 React。每题每天首次获得 5 / 12 / 20 XP，分别对应忘记 / 模糊 / 熟练；同日重复不刷经验。忘记安排 10 分钟后复习，并在本轮末尾追加一次；模糊安排 1 天后复习；熟练按 1、3、7、14、30 天递进。达到 3 次跨天到期熟练复习记为“已扎根”。</p><p style="margin-top:12px">闪卡、手写与 Boss 战采用自查，不会自动执行代码、识别语音或声称 AI 评分。项目卡只提供叙述框架，请填写自己的真实经历。进度保存在当前浏览器，可导出/导入备份。</p><h3 style="margin:22px 0 12px">容易背错的边界，已经补充</h3>${fixed.map(q=>`<p style="margin-bottom:12px"><b>${q.id} · ${esc(q.title)}</b><br>${esc(q.note)}${q.url?` <a href="${esc(q.url)}" target="_blank" rel="noopener">官方依据 ↗</a>`:''}</p>`).join('')}<p class="source">核对日期：2026-10-27。React 18 迁移题保留版本语境；涉及 React 19 的差异单独说明。</p></div>`;$('#detail').showModal();}
function exportState(){save();const blob=new Blob([JSON.stringify({...state,active:null,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`frontend-quest-${E.dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存档已导出，请妥善保存。');}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.nav){nav(d.nav);return;}if(d.chapter!==undefined){const i=Number(d.chapter);start(E.priority(state,Q.filter(q=>q.chapter===i)).slice(0,6).map(q=>q.id),'chapter',chapters[i][1]);return;}if(d.detail){detail(d.detail);return;}if(d.bookmark){toggleBookmark(d.bookmark);return;}if(d.single){$('#detail').close();start([d.single],'recall','主动回忆');return;}if(d.reviewtab){tab=d.reviewtab;render();return;}if(d.choice!==undefined){state.active.selected=Number(d.choice);save();render();return;}if(d.grade!==undefined){grade(Number(d.grade));return;}switch(d.action){case 'daily':{const ids=E.daily(state,Q),left=ids.filter(id=>!today().ids.includes(id));start(left.length?left:[...E.priority(state,Q.filter(q=>q.id.startsWith('J'))).slice(0,3),...E.priority(state,Q.filter(q=>q.id.startsWith('R'))).slice(0,3)].map(q=>q.id),'daily',left.length?'每日冒险':'加练一轮');break;}case 'resume':page='practice';render();break;case 'flash':start(E.priority(state,Q.filter(q=>q.kind==='quiz')).slice(0,6).map(q=>q.id),'flash','记忆闪卡');break;case 'reviewStart':start(E.priority(state,tab==='wrong'?wrong():due()).slice(0,6).map(q=>q.id),'recall','记忆补给');break;case 'reveal':state.active.revealed=true;save();render();setTimeout(()=>$('.feedback')?.scrollIntoView({behavior:'smooth',block:'start'}),30);break;case 'bossStart':start([...E.shuffle(Q.filter(q=>q.id[0]==='J')).slice(0,2),...E.shuffle(Q.filter(q=>q.id[0]==='R')).slice(0,2),...E.shuffle(Q.filter(q=>q.kind!=='quiz')).slice(0,2)].map(q=>q.id),'boss','面试 Boss 战');break;case 'bookmarks':tab=tab==='bookmarks'?'all':'bookmarks';render();break;case 'sources':sources();break;case 'close':$('#detail').close();break;case 'export':exportState();break;case 'import':$('#importFile').click();break;}});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value.slice(0,20000);save();}if(el.id==='search'){search=el.value;$('#libraryRows').innerHTML=libraryRows();}});
document.addEventListener('change',event=>{if(event.target.id==='filter'){filter=event.target.value;$('#libraryRows').innerHTML=libraryRows();}});
$('#importFile').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>3000000)throw Error('存档过大，请选择本应用导出的 JSON 文件');const next=E.validate(JSON.parse(await file.text()),Q.map(q=>q.id));if(confirm('导入将替换当前浏览器的进度、收藏和笔记。建议先导出当前存档。继续吗？')){state=next;save();nav('progress');toast('导入成功，欢迎继续冒险。');}}catch(e){toast('无法导入：'+e.message);}event.target.value='';});
$('#detail').addEventListener('click',event=>{if(event.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('#detail').close();}});
window.addEventListener('storage',event=>{if(event.key===E.KEY)toast('另一标签页更新了存档；请先结束当前操作，再刷新以读取最新进度。');});
render();
